    def on_trade(self, sym, price, qty, sell_aggr, now):
        s = self.s.get(sym)
        o = s["order"] if s else None
        if not o or o["queue"] is None:
            return
        if o["side"] == "buy":
            if not sell_aggr or price > o["price"]:
                return
        elif sell_aggr or price < o["price"]:
            return
        if price == o["price"]:
            o["queue"] -= qty
            if o["queue"] >= 0:
                return
        s["order"] = None
        if o["side"] == "buy":
            self._entered(s, o, now)
        else:
            self._close(s, o["price"], "tp", now)

    def _entered(self, s, o, now):
        c = self.c
        s["pos"] = dict(entry=o["price"], qty=o["qty"], t=now, obi=o["obi"], spr=o["spread"])
        self.log(now, s["name"], "buy_fill", o["price"], "wait=%.1fs" % (now - o["t_place"]))
        tp = o["price"] * (1 + c["TP_BPS"] / 1e4)
        s["order"] = dict(side="sell", price=tp, qty=o["qty"], t_place=now,
                          t_act=now + c["LATENCY"], queue=None)
        self.log(now, s["name"], "tp_order", tp, "")

    def _manage(self, s, now):
        c, p = self.c, s["pos"]
        if s["mkt"]:
            if now >= s["mkt"]["t"]:
                why, s["mkt"] = s["mkt"]["why"], None
                self._close(s, self._walk(s["bids"], p["qty"]), why, now)
            return
        bid = s["bids"][0][0]
        why = None
        if bid <= p["entry"] * (1 - c["SL_BPS"] / 1e4):
            why = "stop"
        elif now - p["t"] >= c["HOLD_SEC"]:
            why = "timeout"
        if why:
            s["order"] = None
            s["mkt"] = dict(t=now + c["LATENCY"], why=why)
            self.log(now, s["name"], why, bid, "")

    @staticmethod
    def _walk(bids, qty):
        need, cost = qty, 0.0
        for p, q in bids:
            take = min(need, q)
            cost += take * p
            need -= take
            if need <= 1e-12:
                break
        if need > 1e-12:
            cost += need * bids[-1][0] * 0.999
        return cost / qty

    def _close(self, s, px, why, now):
        c, p = self.c, s["pos"]
        gross = px / p["entry"] - 1
        fee = 2 * c["FEE"]
        net = gross - fee
        self.db.execute("INSERT INTO trades(ts_open,ts_close,symbol,entry,exit,qty,exit_type,gross_pct,"
                        "fee_pct,net_pct,net_usdt,hold_sec,obi,spread_bps) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        (p["t"], now, s["name"], p["entry"], px, p["qty"], why, gross, fee, net,
                         net * c["NOTIONAL"], now - p["t"], p["obi"], p["spr"]))
        self.db.commit()
        self.log(now, s["name"], "exit_" + why, px, "net=%.3f%%" % (net * 100))
        s["pos"], s["order"], s["mkt"] = None, None, None
        s["cool"] = now + c["COOLDOWN"]

    # ---------- для панели ----------
    def snapshot(self):
        now, cur = time.time(), self.db.cursor()
        syms = []
        for s in self.s.values():
            d = dict(name=s["name"], obi=round(s["obi"], 2), spread=round(s["spread"], 2),
                     bid=s["bids"][0][0] if s["bids"] else None,
                     age=round(now - s["t_book"], 1) if s["t_book"] else None)
            d["state"] = ("выход" if s["mkt"] else "в позиции") if s["pos"] else ("заявка" if s["order"] else "ждёт")
            if s["pos"] and s["bids"]:
                d["pnl_bps"] = round((s["bids"][0][0] / s["pos"]["entry"] - 1) * 1e4 - 2 * self.c["FEE"] * 1e4, 1)
            syms.append(d)
        q = cur.execute
        return dict(
            up=int(now - self.t0), syms=syms, cfg=self.c,
            tot=q("SELECT COUNT(*),COALESCE(SUM(net_usdt),0),COALESCE(AVG(net_pct),0)*100,"
                  "COALESCE(AVG(gross_pct),0)*100,COALESCE(SUM(net_pct>0),0) FROM trades").fetchone(),
            by_exit=q("SELECT exit_type,COUNT(*),AVG(net_pct)*100 FROM trades GROUP BY exit_type").fetchall(),
            by_sym=q("SELECT symbol,COUNT(*),SUM(net_usdt),AVG(net_pct)*100 FROM trades GROUP BY symbol").fetchall(),
            ev=dict(q("SELECT kind,COUNT(*) FROM events GROUP BY kind").fetchall()),
            sig=q("SELECT COUNT(*),AVG((mid30/mid0-1)*1e4),AVG((mid60/mid0-1)*1e4) FROM signals").fetchone(),
            last=q("SELECT ts_close,symbol,exit_type,entry,exit,net_pct*100,hold_sec FROM trades "
                   "ORDER BY id DESC LIMIT 12").fetchall(),
            evl=q("SELECT ts,symbol,kind,price,info FROM events ORDER BY id DESC LIMIT 12").fetchall())


